(async () => {

  // -- step 1: prepare --
  // Validate the image path and set up global state
  const {existsSync}=await import('node:fs');
  const imagePath=process.env.IMAGE_PATH;
  if(!imagePath){throw new Error('IMAGE_PATH env var not set');}
  if(!existsSync(imagePath)){throw new Error(`Image file not found: ${imagePath}`);}
  globalThis.imagePath=imagePath;

  // -- step 2: execute --
  // Create a PDF containing the title, image, and rendered markdown, handling pagination and font sizes
  const {readFileSync}=await import('node:fs');
  const {PDFDocument, StandardFonts}=await import('pdf-lib');
  const imageBytes=readFileSync(globalThis.imagePath);
  const pdfDoc=await PDFDocument.create();
  const pngImage=await pdfDoc.embedPng(imageBytes);
  const helvetica=await pdfDoc.embedFont(StandardFonts.Helvetica);
  const helveticaBold=await pdfDoc.embedFont(StandardFonts.HelveticaBold);
  const margin=50;
  let page=pdfDoc.addPage();
  let {width,height}=page.getSize();
  // draw title centered 40 points below top of page
  const title="Example.com Screenshot";
  const titleSize=24;
  const titleWidth=helveticaBold.widthOfTextAtSize(title,titleSize);
  page.drawText(title,{x:(width-titleWidth)/2, y:height-40, size:titleSize, font:helveticaBold});
  // set y coordinate for image directly below title (5pt gap)
  let y=height-40-titleSize-5;
  // embed image on the left
  const imgDims=pngImage.scale(1);
  page.drawImage(pngImage,{x:margin, y:y-imgDims.height, width:imgDims.width, height:imgDims.height});
  let textX=margin+imgDims.width+20;
  let textY=y;
  const md=`# Sample Heading
  ## Subheading
  - Item one
  - Item two

  This is a paragraph of body text that should wrap onto multiple lines if it exceeds the page width.`;
  function drawLine(txt,size,font){
    const maxWidth=width-margin-textX;
    const words=txt.split(' ');
    let line='';
    for(const w of words){
      const test=line? line+' '+w:w;
      const testWidth=font.widthOfTextAtSize(test,size);
      if(testWidth>maxWidth){
        page.drawText(line,{x:textX,y:textY,size,font});
        textY-=size+4;
        if(textY<margin){
          page=pdfDoc.addPage();
          ({width,height}=page.getSize());
          textY=height-margin;
        }
        line=w;
      }else{
        line=test;
      }
    }
    if(line){
      page.drawText(line,{x:textX,y:textY,size,font});
      textY-=size+4;
      if(textY<margin){
        page=pdfDoc.addPage();
        ({width,height}=page.getSize());
        textY=height-margin;
      }
    }
  }
  for(const rawLine of md.split('\\n')){
    if(rawLine.startsWith('# ')){
      drawLine(rawLine.replace(/^# /,''),24,helveticaBold);
    }else if(rawLine.startsWith('## ')){
      drawLine(rawLine.replace(/^## /,''),18,helveticaBold);
    }else if(rawLine.startsWith('- ')){
      drawLine('• '+rawLine.slice(2),12,helvetica);
    }else if(rawLine.trim()===''){
      textY-=12; // paragraph spacing
    }else{
      drawLine(rawLine,12,helvetica);
    }
  }
  const pdfBytes=await pdfDoc.save();
  globalThis.pdfBytes=pdfBytes;

  // -- step 3: emit --
  // Output a JSON object with the PDF base64 string
  const base64=Buffer.from(globalThis.pdfBytes).toString('base64');
  console.log(JSON.stringify({pdf_base64:base64}));

})().catch(e => { console.error(String((e && e.stack) || e)); process.exit(1); });
